def minDistinctAfterRemovals(nums, k):
    cnt = {}
    for x in nums:
        cnt[x] = cnt.get(x, 0) + 1
    freqs = sorted(cnt.values())
    gone = 0
    for f in freqs:
        if k >= f:
            k -= f
            gone += 1
        else:
            break
    return len(freqs) - gone
